#Requires -Version 5.1
[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$InvocationManifest,[switch]$Preflight,[switch]$Collect)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if(([bool]$Preflight)-eq([bool]$Collect)){throw 'Specify exactly one of -Preflight or -Collect.'}
function Assert-O3F14([bool]$Condition,[string]$Message){if(-not$Condition){throw $Message}}
function Get-O3F14Hash([string]$Path){return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash}
function Get-O3F14BytesHash([byte[]]$Bytes){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-','')}finally{$sha.Dispose()}}
function Write-O3F14Bytes([Parameter(Mandatory=$true)][AllowEmptyCollection()][byte[]]$Bytes){$PSCmdlet.WriteObject($Bytes,$false)}
function Read-O3F14Entry([IO.Compression.ZipArchive]$Archive,[string]$Name,[int64]$MaximumBytes){$entry=$Archive.GetEntry($Name);Assert-O3F14 ($null-ne$entry-and$entry.Length-le$MaximumBytes) "O3F14 response entry absent or oversized: $Name";$stream=$entry.Open();$memory=New-Object IO.MemoryStream;try{$stream.CopyTo($memory);Write-O3F14Bytes -Bytes ([byte[]]$memory.ToArray())}finally{$stream.Dispose();$memory.Dispose()}}
function Write-O3F14Json([string]$Path,[object]$Value){Assert-O3F14 (-not(Test-Path -LiteralPath $Path)) "O3F14 collection gate exists: $Path";[IO.File]::WriteAllText($Path,(($Value|ConvertTo-Json -Depth 16)+[Environment]::NewLine),(New-Object Text.UTF8Encoding($false)))}
