$project=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'));$invocationPath=[IO.Path]::GetFullPath($InvocationManifest);$expected=Join-Path $PSScriptRoot 'O3F14_RESPONSE_COLLECTION_INVOCATION.json';Assert-O3F14 ($invocationPath.Equals($expected,[StringComparison]::OrdinalIgnoreCase)) 'O3F14 collection invocation path changed.'
$invoke=Get-Content -LiteralPath $invocationPath -Raw|ConvertFrom-Json;Assert-O3F14 ([string]$invoke.schema-eq'argos_ocv03_o3f14_response_collection_invocation_v1'-and[string]$invoke.state-eq'FROZEN_EXACT_RESPONSE_COLLECTION_INVOCATION'-and[string]$invoke.collectorSha256-eq(Get-O3F14Hash $PSCommandPath)) 'O3F14 collection invocation is not frozen.'
$sourceZip=[IO.Path]::GetFullPath([string]$invoke.sourceZip);Assert-O3F14 (Test-Path -LiteralPath $sourceZip -PathType Leaf) 'O3F14 response ZIP is absent.';Assert-O3F14 ((Get-Item $sourceZip).Length-eq[int64]$invoke.sourceZipBytes-and(Get-O3F14Hash $sourceZip)-eq[string]$invoke.sourceZipSha256) 'O3F14 response ZIP identity changed.'
$certificate=Join-Path $project ([string]$invoke.endpointCertificate);Assert-O3F14 ((Get-O3F14Hash $certificate)-eq[string]$invoke.endpointCertificateSha256) 'O3F14 endpoint certificate changed.'
Add-Type -AssemblyName System.IO.Compression;Add-Type -AssemblyName System.IO.Compression.FileSystem;$archive=[IO.Compression.ZipFile]::OpenRead($sourceZip)
try{$names=@($archive.Entries|ForEach-Object{[string]$_.FullName}|Sort-Object);$expectedNames=@('MAINTENANCE.stderr.txt','MAINTENANCE.stdout.txt','PORTAL_RESPONSE_MANIFEST.json','PORTAL_RESPONSE_MANIFEST.sig','RESULT.json')|Sort-Object;Assert-O3F14 ($names.Count-eq5-and@(Compare-Object $expectedNames $names).Count-eq0) 'O3F14 response entry set changed.';$manifestBytes=Read-O3F14Entry $archive 'PORTAL_RESPONSE_MANIFEST.json' 65536;$signatureBytes=Read-O3F14Entry $archive 'PORTAL_RESPONSE_MANIFEST.sig' 8192;$stdoutBytes=Read-O3F14Entry $archive 'MAINTENANCE.stdout.txt' 1048576;$stderrBytes=Read-O3F14Entry $archive 'MAINTENANCE.stderr.txt' 65536;$resultBytes=Read-O3F14Entry $archive 'RESULT.json' 65536}finally{$archive.Dispose()}
Assert-O3F14 ($stderrBytes.Length-eq0) 'O3F14 maintenance stderr is not empty.';$manifest=[Text.Encoding]::UTF8.GetString($manifestBytes)|ConvertFrom-Json;$endpoint=[Text.Encoding]::UTF8.GetString($stdoutBytes)|ConvertFrom-Json;$maintenance=[Text.Encoding]::UTF8.GetString($resultBytes)|ConvertFrom-Json
Assert-O3F14 ([string]$manifest.requestId-eq[string]$invoke.requestId-and[string]$manifest.responseId-eq[string]$invoke.responseId-and[string]$manifest.state-eq'PASS_MAINTENANCE_PATCH'-and[string]$manifest.sourceRole-eq'JBOD') 'O3F14 response correlation/state changed.'
$cert=New-Object Security.Cryptography.X509Certificates.X509Certificate2($certificate);$rsa=[Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($cert);try{$valid=$rsa.VerifyData($manifestBytes,$signatureBytes,[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.RSASignaturePadding]::Pkcs1)}finally{$rsa.Dispose()};Assert-O3F14 ($valid-and$cert.Thumbprint.ToUpperInvariant()-eq[string]$invoke.expectedSignerThumbprint) 'O3F14 response signature failed.'
$actual=@{'MAINTENANCE.stderr.txt'=$stderrBytes;'MAINTENANCE.stdout.txt'=$stdoutBytes;'RESULT.json'=$resultBytes};Assert-O3F14 (@($manifest.files).Count-eq3) 'O3F14 response declared-file count changed.';foreach($record in @($manifest.files)){$name=[string]$record.path;Assert-O3F14 ($actual.ContainsKey($name)) "O3F14 unexpected response file: $name";$bytes=[byte[]]$actual[$name];Assert-O3F14 ($bytes.Length-eq[int64]$record.bytes-and(Get-O3F14BytesHash $bytes)-eq[string]$record.sha256) "O3F14 response file hash changed: $name"}
Assert-O3F14 ([string]$maintenance.state-eq'PASS_MAINTENANCE_PATCH'-and[int]$maintenance.exitCode-eq0-and[string]$maintenance.entryPoint-eq'payload/Invoke-O3F14StagedEndpoint.ps1') 'O3F14 maintenance result changed.'
Assert-O3F14 ([string]$endpoint.schema-eq'argos_ocv03_o3f14_staged_endpoint_result_v1'-and[string]$endpoint.state-eq'COMPLETE_O3F14_GATE_AND_DEV6_RESULTS_RETURNED_REVIEW_ONLY'-and-not[bool]$endpoint.rehearsal-and@($endpoint.dev6.cases).Count-eq6) 'O3F14 endpoint terminal result changed.'
