Assert-O3F14 ([string]$endpoint.rootContract.schema-eq'argos_ocv03_o3f14_exact_runner_root_contract_v1'-and[string]$endpoint.rootContract.state-eq'PASS_O3F14_EXACT_REAL_RUNNER_ROOT_CONTRACT'-and[string]$endpoint.rootContract.runnerSha256-eq$expectedRunnerSha256-and[string]$endpoint.rootContract.gateRoot-eq'D:/O3F9G14'-and[string]$endpoint.rootContract.dev6Root-eq'D:/O3F9D14'-and[string]::Join('|',@($endpoint.rootContract.gateTerminalKeys))-ceq'commands|stage|state|summarySha256'-and[string]::Join('|',@($endpoint.rootContract.dev6TerminalKeys))-ceq'aliasEvidence|executedCount|newProviderHoldCount|results|selectedCount|stage|state|stateCounts|summarySha256'-and-not[bool]$endpoint.rootContract.simulatedFilesystem-and[bool]$endpoint.rootContract.incompatibleO3F14PrefixRejected-and-not[bool]$endpoint.rootContract.sourceImageBytesRead-and-not[bool]$endpoint.rootContract.outputCreated-and-not[bool]$endpoint.rootContract.mutationsPerformed) 'O3F14 live root/schema-contract evidence changed.'
