Assert-O3F14 ([string]$aliasContract.planSha256-eq$expectedAliasPlanSha256-and[string]$aliasContract.schema-eq'argos_ocv03_o3f12_dev6_source_alias_plan_v1'-and[string]$aliasContract.state-eq'FROZEN_FOR_BUILD'-and[string]$aliasContract.aliasDrive-ceq'Q:'-and[int]$aliasContract.caseCount-eq6-and[int]$aliasContract.canonicalLeafCount-eq12-and[int]$aliasContract.aliasLeafCount-eq12-and[bool]$aliasContract.broadRootSlot16Rejected-and-not[bool]$aliasContract.sourceImageBytesRead-and[string]$aliasContract.substSha256-eq$expectedSubstSha256-and([string]$aliasContract.substPath).Replace('\','/')-ceq'C:/Windows/System32/subst.exe'-and-not[bool]$aliasContract.lifecycle.exercised-and[bool]$aliasContract.lifecycle.metadataStaticChecksOnly) 'O3F14 frozen root source-alias contract changed.'
$dev6ChildExitCode=[int]$endpoint.dev6.childExitCode;$dev6State=[string]$endpoint.dev6.state;$dev6Cases=@($endpoint.dev6.cases);$dev6ExecutedCount=[int]$endpoint.dev6.executedCount;$dev6HoldCount=[int]$endpoint.dev6.newProviderHoldCount
